// ensureProjectScopeSecretClusterLabel ensures that all project scoped secrets in the
// project's backing namespace carry the ProjectScopedSecretClusterLabel label set to the
// project's cluster name. Secrets that already have the label are skipped. Any update
// errors are accumulated and returned without stopping on the first failure.
func (n *namespaceHandler) ensureProjectScopeSecretClusterLabel(project *v3.Project) error {
	backingNamespace := project.GetProjectBackingNamespace()

	r, err := labels.NewRequirement(ProjectScopedSecretLabel, selection.Exists, nil)
	if err != nil {
		return err
	}
	secrets, err := n.managementSecretCache.List(backingNamespace, labels.NewSelector().Add(*r))
	if err != nil {
		return err
	}

	var errs error
	for _, s := range secrets {
		if _, ok := s.Labels[ProjectScopedSecretClusterLabel]; ok {
			continue
		}
		secretCopy := s.DeepCopy()
		if secretCopy.Labels == nil {
			secretCopy.Labels = map[string]string{}
		}
		secretCopy.Labels[ProjectScopedSecretClusterLabel] = project.Spec.ClusterName
		_, err := n.managementSecretClient.Update(secretCopy)
		errs = errors.Join(errs, err)
	}

	return errs
